"""Generated by deploy/build_bundle.py from contracts/reading.py and contracts/signal.py.
Comments removed to keep the deploy small; read them in those files."""
READ = 'read'
ABSENT = 'absent'
UNREADABLE = 'unreadable'
_MAX_FIELDS = 6
_MAX_PATH = 64
_MAX_KEY = 64

def valid_host(host: str) -> bool:
    h = (host or '').strip().lower()
    if not h or len(h) > 100 or h.startswith('.') or h.endswith('.') or ('..' in h):
        return False
    for ch in h:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-.'):
            return False
    return '.' in h

def valid_path(path: str) -> bool:
    p = (path or '').strip()
    if not p.startswith('/') or len(p) > 200:
        return False
    if '..' in p or '://' in p or '?' in p or ('#' in p) or ('//' in p):
        return False
    return p.count('{key}') == 1

def valid_key(key: str) -> bool:
    k = (key or '').strip()
    if not k or len(k) > _MAX_KEY:
        return False
    for ch in k:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or 'A' <= ch <= 'Z' or (ch in '-_')):
            return False
    return True

def valid_field_path(path: str) -> bool:
    if not path or len(path) > _MAX_PATH:
        return False
    if path.startswith('.') or path.endswith('.') or '..' in path:
        return False
    for ch in path:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or 'A' <= ch <= 'Z' or (ch in '._-')):
            return False
    return True

def parse_fields(fields: str) -> list:
    out = []
    for raw in (fields or '').split(','):
        path = raw.strip()
        if not path:
            continue
        if not valid_field_path(path):
            raise ValueError('bad field path: ' + repr(path))
        if path in out:
            raise ValueError('duplicate field path: ' + repr(path))
        out.append(path)
    if not out:
        raise ValueError('a feed needs at least one field path')
    if len(out) > _MAX_FIELDS:
        raise ValueError(f'at most {_MAX_FIELDS} fields per feed')
    return out

def pick(document, path: str) -> str:
    node = document
    for part in path.split('.'):
        if isinstance(node, dict):
            if part not in node:
                return ''
            node = node[part]
        elif isinstance(node, list):
            if not part.isdigit():
                return ''
            i = int(part)
            if i >= len(node):
                return ''
            node = node[i]
        else:
            return ''
    if node is None:
        return ''
    if isinstance(node, (dict, list)):
        return ''
    if node is True:
        return 'true'
    if node is False:
        return 'false'
    return str(node)

def extract(document, paths: list) -> tuple:
    values = [pick(document, p) for p in paths]
    return (values, any((v != '' for v in values)))

def join_values(values: list) -> str:
    for v in values:
        if '\n' in v:
            raise ValueError('a value may not contain a newline')
    return '\n'.join(values)

def split_values(blob: str, count: int) -> list:
    parts = (blob or '').split('\n') if blob else []
    while len(parts) < count:
        parts.append('')
    return parts[:count]
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *

@gl.storage.allow
@dataclass
class Feed:
    host: str
    path: str
    fields: str
    creator: Address
    registered_at: str

@gl.storage.allow
@dataclass
class Reading:
    feed: str
    key: str
    status: str
    values: str
    url: str
    read_at: str

class Signal(gl.contract.Contract):
    feeds: gl.storage.TreeMap[str, Feed]
    feed_ids: gl.storage.DynArray[str]
    readings: gl.storage.TreeMap[str, Reading]

    def __init__(self):
        pass

    @gl.public.write
    def register(self, name: str, host: str, path: str, fields: str) -> dict:
        label = name.strip().lower()
        if not label or len(label) > 40:
            raise gl.vm.UserError('name the feed')
        for ch in label:
            if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-_'):
                raise gl.vm.UserError('a feed name is letters, digits, hyphen or underscore')
        owner = gl.message.sender_address
        feed_id = owner.as_hex.lower() + ':' + label
        if feed_id in self.feeds:
            raise gl.vm.UserError('that feed already exists and cannot be changed')
        clean_host = host.strip().lower()
        if not valid_host(clean_host):
            raise gl.vm.UserError('host must be a bare hostname, with no scheme, port or path')
        clean_path = path.strip()
        if not valid_path(clean_path):
            raise gl.vm.UserError('path must start at / and contain {key} exactly once')
        paths = parse_fields(fields)
        self.feeds[feed_id] = Feed(host=clean_host, path=clean_path, fields=','.join(paths), creator=owner, registered_at=_stamp())
        self.feed_ids.append(feed_id)
        return self.get_feed(feed_id)

    @gl.public.write
    def read(self, feed_id: str, key: str) -> dict:
        fid = feed_id.strip().lower()
        if fid not in self.feeds:
            raise gl.vm.UserError('no such feed: ' + fid)
        feed = self.feeds[fid]
        ref = key.strip()
        if not valid_key(ref):
            raise gl.vm.UserError('a key is ASCII letters, digits, hyphen or underscore')
        url = 'https://' + feed.host + feed.path.replace('{key}', ref)
        paths = [p for p in feed.fields.split(',') if p]

        def leader_fn():
            return _probe(url, paths)

        def validator_fn(leaders_res) -> bool:
            if not isinstance(leaders_res, gl.vm.Return):
                return False
            leader = leaders_res.calldata
            if not isinstance(leader, dict) or 'status' not in leader or 'values' not in leader:
                return False
            mine = _probe(url, paths)
            if mine['status'] == UNREADABLE:
                return str(leader['status']) == UNREADABLE
            if str(leader['status']) == UNREADABLE:
                return False
            return str(leader['status']) == mine['status'] and str(leader['values']) == mine['values']
        agreed = gl.vm.run_nondet(leader_fn, validator_fn)
        status = str(agreed['status'])
        values = str(agreed['values'])
        if status not in (READ, ABSENT, UNREADABLE):
            raise gl.vm.UserError('unknown reading status')
        record = Reading(feed=fid, key=ref, status=status, values=values if status != UNREADABLE else '', url=url, read_at=_stamp())
        self.readings[_slot(fid, ref)] = record
        return _reading_dict(record, paths)

    @gl.public.view
    def get_reading(self, feed_id: str, key: str) -> dict:
        fid = feed_id.strip().lower()
        ref = key.strip()
        slot = _slot(fid, ref)
        if slot not in self.readings:
            return {'feed': fid, 'key': ref, 'status': '', 'values': {}, 'url': '', 'read_at': ''}
        paths = []
        if fid in self.feeds:
            paths = [p for p in self.feeds[fid].fields.split(',') if p]
        return _reading_dict(self.readings[slot], paths)

    @gl.public.view
    def value_of(self, feed_id: str, key: str, field: str) -> str:
        record = self.get_reading(feed_id, key)
        values = record['values']
        if not isinstance(values, dict):
            return ''
        return str(values.get(field.strip(), ''))

    @gl.public.view
    def get_feed(self, feed_id: str) -> dict:
        fid = feed_id.strip().lower()
        if fid not in self.feeds:
            raise gl.vm.UserError('no such feed: ' + fid)
        feed = self.feeds[fid]
        return {'feed_id': fid, 'host': feed.host, 'path': feed.path, 'fields': [p for p in feed.fields.split(',') if p], 'creator': feed.creator.as_hex, 'registered_at': feed.registered_at, 'example_url': 'https://' + feed.host + feed.path}

    @gl.public.view
    def feed_list(self) -> list:
        return [f for f in self.feed_ids]

    @gl.public.view
    def count(self) -> int:
        return len(self.feed_ids)

def _slot(feed_id: str, key: str) -> str:
    return feed_id + '|' + key

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _probe(url: str, paths: list) -> dict:
    import json
    try:
        resp = gl.nondet.web.get(url)
        status = int(resp.status)
        body = (resp.body or b'').decode('utf-8', errors='replace')
    except Exception:
        return {'status': UNREADABLE, 'values': ''}
    if status == 404:
        return {'status': ABSENT, 'values': join_values(['' for _ in paths])}
    if status < 200 or status >= 300:
        return {'status': UNREADABLE, 'values': ''}
    try:
        document = json.loads(body)
    except Exception:
        return {'status': UNREADABLE, 'values': ''}
    values, present = extract(document, paths)
    try:
        blob = join_values(values)
    except ValueError:
        return {'status': UNREADABLE, 'values': ''}
    return {'status': READ if present else ABSENT, 'values': blob}

def _reading_dict(record: Reading, paths: list) -> dict:
    values = split_values(record.values, len(paths))
    return {'feed': record.feed, 'key': record.key, 'status': record.status, 'values': {paths[i]: values[i] for i in range(len(paths))}, 'url': record.url, 'read_at': record.read_at}
